rss.channel:
ONIZOUKA SHOP - Catalogue Officiel
{{ base_url }}
Catalogue officiel des produits électroménager et électronique Onizouka Shop Bamako
{% for product in products %}


  {{ product.sku|default:product.id }}
  {{ product.name }}
  {{ product.description|default:product.short_description|default:product.name|striptags|truncatewords:45 }}
  {{ base_url }}{{ product.get_absolute_url }}
  {% if product.primary_image %}
  {{ base_url }}{{ product.primary_image.image.url }}
  {% endif %}
  {{ product.brand.name|default:"Onizouka Shop" }}
  new
  {% if product.stock > 0 %}in stock{% else %}out of stock{% endif %}
  {{ product.price|floatformat:0 }} XOF
  {% if product.is_on_sale and product.sale_price %}
  {{ product.sale_price|floatformat:0 }} XOF
  {% endif %}
  {{ product.category.name }}
  Electronics

{% endfor %}
